export default async function next({ previous, bucket, region }, context) {
  if (typeof bucket !== "string" || !bucket.trim() || bucket.startsWith("YOUR_"))
    throw Error("Configure S3 bucket");
  if (typeof region !== "string" || !/^[a-z]{2}(?:-[a-z]+){1,2}-[0-9]+$/.test(region))
    throw Error("Configure AWS region");
  const s = previous ?? { cursor: null, count: 0 };
  const r = await context.actions.call("aws_s3.list_objects", {
    bucket,
    region,
    maxKeys: 1,
    ...(s.cursor ? { continuationToken: s.cursor } : {}),
  });
  if (!Array.isArray(r?.objects) || r.objects.length > 1 || typeof r.isTruncated !== "boolean")
    throw Error("Invalid S3 page");
  const next = r.isTruncated ? r.nextContinuationToken : null;
  if (r.isTruncated && (typeof next !== "string" || !next || next === s.cursor))
    throw Error("Invalid S3 continuation token");
  const item = r.objects[0];
  if (
    item &&
    (typeof item.name !== "string" ||
      !item.name ||
      !Number.isSafeInteger(item.size) ||
      item.size < 0)
  )
    throw Error("Invalid S3 object");
  const include = !!item && item.size > 0 && !item.name.endsWith("/");
  return {
    state: { cursor: next, count: s.count + (include ? 1 : 0) },
    hasObject: include,
    more: r.isTruncated,
    key: include ? item.name : "-",
    bucket,
    region,
  };
}

